-- свой набор сервисов у бренда (тот же список — build/brand/exclude.json): товары без заказов удаляем, с заказами — скрываем
delete from products p where p.slug in ('artflow','character-ai','chaton','deezer','dribbble','emochi','endel','envato','istock','kaiber','kling','leonardo','lexica','magic','make','memex','moescape','nijijourney','novelai','pixellab','revid','sentry','suno','tunecore','vamos','webflow-ai') and not exists (select 1 from orders o where o.product_id = p.id);
update products set active = false where slug in ('artflow','character-ai','chaton','deezer','dribbble','emochi','endel','envato','istock','kaiber','kling','leonardo','lexica','magic','make','memex','moescape','nijijourney','novelai','pixellab','revid','sentry','suno','tunecore','vamos','webflow-ai');
